const object = (x) => !!x && typeof x === "object" && !Array.isArray(x);
const clone = (x) => JSON.parse(JSON.stringify(x));
export const empty = () => ({
  version: 5,
  translation: "otb",
  paths: [],
  journal: [],
  highlights: [],
  reflections: [],
  quiz: {},
  events: [],
  reading: null,
  reminderSnoozes: {},
  dismissedGaps: {},
  reviews: [],
  guidedPlans: {},
  settings: {},
});
const arrays = [
  "paths",
  "journal",
  "highlights",
  "reflections",
  "events",
  "reviews",
];
export function validateShape(raw, strict = false) {
