    ...p,
    steps: (p.steps || []).map((x) => ({ ...x, id: String(x.id || id()) })),
    milestones: (p.milestones || []).map((x) => ({
      ...x,
      id: String(x.id || id()),
    })),
    reviews: (p.reviews || []).map((x) => ({ ...x, id: String(x.id || id()) })),
    links: (p.links || []).map((x) => ({ ...x, id: String(x.id || id()) })),
